import importlib.util
import os
import socket
import subprocess
import sys
from pathlib import Path

import pytest

SCRIPT = Path(__file__).parents[1] / "app" / "slicer_link" / "filaman_slicer_link.py"
_spec = importlib.util.spec_from_file_location("filaman_slicer_link", SCRIPT)
sl = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(sl)


def _parse(text):
    return sl.parse_gcode_lines([line.strip() for line in text.splitlines() if line.startswith(";")])


PRUSA = """\
; generated by PrusaSlicer 2.8.0 on 2026-11-01 at 10:00:00 UTC
G1 X0
; filament used [mm] = 1000.50, 250.00
; filament used [cm3] = 2.4, 0.6
; filament used [g] = 3.10, 0.80
; total filament used [g] = 3.90
; estimated printing time (normal mode) = 1d 2h 3m 4s
; filament_type = PLA;PETG
; filament_colour = #ff0000;#00FF00
; printer_model = MK4S
"""

ORCA = """\
; BambuStudio 02.03.00.62
; model printing time: 1h 2m 3s; total estimated time: 1h 5m 3s
; total filament weight [g] : 25.5
; filament used [mm] = 100.0,0.00,300.0,0.00
; filament used [g] = 10.5,0.00,15.0,0.00
; filament_type = PLA;PETG;PLA;ABS
; filament_colour = #FFFFFF;#000000;#0000FF;#00FF00
"""


def test_prusa_lists_weights_lengths_types_colors_time():
    parsed = _parse(PRUSA)
    assert parsed["slicer"] == "PrusaSlicer"
    assert parsed["slicer_version"] == "2.8.0"
    assert parsed["print_time_s"] == 86400 + 2 * 3600 + 3 * 60 + 4
    assert parsed["printer_model"] == "MK4S"
    assert parsed["filaments"] == [
        {"index": 0, "weight_g": 3.1, "length_mm": 1000.5, "material": "PLA", "color_hex": "#FF0000"},
        {"index": 1, "weight_g": 0.8, "length_mm": 250.0, "material": "PETG", "color_hex": "#00FF00"},
    ]


def test_orca_bambu_multicolor_keeps_indices_and_skips_unused():
    parsed = _parse(ORCA)
    assert parsed["slicer"] == "BambuStudio"
    assert parsed["print_time_s"] == 3903  # total estimated time wins
    assert [f["index"] for f in parsed["filaments"]] == [0, 2]
    assert parsed["filaments"][1]["weight_g"] == 15.0
    assert parsed["filaments"][1]["material"] == "PLA"
    assert parsed["filaments"][1]["color_hex"] == "#0000FF"


def test_dual_nozzle_blocks_are_summed_not_first_value_only():
    parsed = _parse(
        "; filament used [g] = 1.0, 2.0\n; filament used [g] = 4.0, 0.5\n; filament used [mm] = 100, 200\n"
    )
    assert [f["weight_g"] for f in parsed["filaments"]] == [5.0, 2.5]


def test_cura_meters_and_time():
    parsed = _parse(";Generated with Cura_SteamEngine 5.7.1\n;TIME:1234\n;Filament used: 1.234m, 0.5m\n")
    assert parsed["slicer"] == "Cura"
    assert parsed["slicer_version"] == "5.7.1"
    assert parsed["print_time_s"] == 1234
    assert parsed["filaments"] == [{"index": 0, "length_mm": 1234.0}, {"index": 1, "length_mm": 500.0}]


def test_missing_values_give_no_filaments_and_total_only_is_one_filament():
    assert _parse("; nothing useful\n")["filaments"] == []
    parsed = _parse("; total filament used [g] = 7.5\n")
    assert parsed["filaments"] == [{"index": 0, "weight_g": 7.5}]
    assert parsed["print_time_s"] is None


def test_gcode_file_unicode_and_invalid_bytes(tmp_path):
    path = tmp_path / "Würfel_äöü ✓.gcode"
    path.write_bytes(PRUSA.encode("utf-8") + b"; broken \xff\xfe bytes\n")
    parsed = sl.parse_gcode_file(str(path))
    assert len(parsed["filaments"]) == 2
    assert sl.job_name(str(path), parsed, environ={}) == "Würfel_äöü ✓"


def test_large_file_reads_head_and_tail_without_double_counting(tmp_path):
    path = tmp_path / "big.gcode"
    filler = ("G1 X1 Y1 E0.1 ; move\n" * 100000).encode()  # ~2.1 MB
    with open(path, "wb") as handle:
        handle.write(b"; filament used [g] = 2.0\n" + filler * 2 + b"; filament used [g] = 2.0\n")
    assert sl.parse_gcode_file(str(path))["filaments"] == [{"index": 0, "weight_g": 2.0}]


def test_job_name_sources():
    assert sl.job_name("/tmp/x/Benchy.gcode", None, {"SLIC3R_PP_OUTPUT_NAME": "/out/Vase.gcode"}) == "Vase"
    assert sl.job_name("/tmp/x/Benchy.gcode", None, {}) == "Benchy"
    # Bambu temp files with number names fall back to the model name, then to the file name
    assert sl.job_name("/tmp/12345678.gcode", {"model_name": "Hook"}, {}) == "Hook"
    assert sl.job_name("/tmp/12345678.gcode", {}, {}) == "12345678"


def test_model_name_comment_is_parsed():
    assert _parse("; model name: Haken\n; filament used [g] = 1\n")["model_name"] == "Haken"


def test_parse_map_and_duration():
    assert sl.parse_map("0=1, 1=2,x=3,4") == {0: 1, 1: 2}
    assert sl.parse_duration("2m 5s") == 125
    assert sl.parse_duration("n/a") is None


def _free_port():
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        return sock.getsockname()[1]


def test_unreachable_server_exits_zero_and_logs(tmp_path):
    gcode = tmp_path / "a.gcode"
    gcode.write_text(PRUSA, encoding="utf-8")
    env = {**os.environ, "HOME": str(tmp_path), "USERPROFILE": str(tmp_path)}
    result = subprocess.run(
        [sys.executable, str(SCRIPT), "--url", f"http://127.0.0.1:{_free_port()}", "--key", "uak.1.x", "--printer", "1", str(gcode)],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    assert result.returncode == 0
    assert (tmp_path / ".filaman_slicer_link.log").read_text(encoding="utf-8").strip() != ""


def test_garbage_arguments_and_test_mode_exit_zero(tmp_path):
    env = {**os.environ, "HOME": str(tmp_path), "USERPROFILE": str(tmp_path)}
    bad = subprocess.run([sys.executable, str(SCRIPT), "--printer", "abc"], env=env, capture_output=True, text=True, timeout=30)
    assert bad.returncode == 0
    probe = subprocess.run(
        [sys.executable, str(SCRIPT), "--test", "--url", f"http://127.0.0.1:{_free_port()}", "--key", "k"],
        env=env,
        capture_output=True,
        text=True,
        timeout=30,
    )
    assert probe.returncode == 0
    assert "FAILED" in probe.stdout
